import type { ShellSyntax } from "../../src/shell.ts";
import type { ApprovalHelpers } from "./approval.ts";

export interface FlatShellSegment {
	readonly text: string;
	readonly pipedStdin: boolean;
}

export interface WorktreeRewriteHelpers {
	readonly rewriteGitWorktreeAdd: (command: string, cli: readonly string[]) => string;
	readonly extractFlatShellCommandSegments: (command: string) => readonly FlatShellSegment[];
	readonly approval: Pick<ApprovalHelpers, "tokenizeShellSegments">;
}

const CMD_META = /([()\][%!^"`<>&|;, *?])/g;

function cmdArgument(value: string): string {
	const escaped = value.replace(/(?=(\\+?)?)\1"/g, '$1$1\\"').replace(/(?=(\\+?)?)\1$/g, "$1$1");
	return `"${escaped}"`.replace(CMD_META, "^$1");
}

/** Called only with the literal argv produced by the host rewriter. */
export function renderInvocation(argv: readonly string[], syntax: "powershell" | "cmd"): string {
	if (syntax === "powershell") return `& ${argv.map((part) => `'${part.replaceAll("'", "''")}'`).join(" ")}`;
	return [argv[0].replace(CMD_META, "^$1"), ...argv.slice(1).map(cmdArgument)].join(" ");
}

export function rewriteForShell(
	command: string,
	cli: readonly string[],
	syntax: ShellSyntax,
	helpers: WorktreeRewriteHelpers,
): string {
	// Whole-command admission preserves the host's piped-stdin rejection.
	const rewritten = helpers.rewriteGitWorktreeAdd(command, cli);
	if (rewritten === command || syntax === "command-c") return rewritten;
	let cursor = 0;
	let result = "";
	for (const segment of helpers.extractFlatShellCommandSegments(command)) {
		const start = command.indexOf(segment.text, cursor);
		if (start < 0) throw new Error("omp-unified-exec: host worktree segment is not in its source command");
		result += command.slice(cursor, start);
		const generated = helpers.rewriteGitWorktreeAdd(segment.text, cli);
		if (generated === segment.text) {
			result += segment.text;
		} else {
			const invocations = helpers.approval.tokenizeShellSegments(generated);
			if (invocations.length !== 1 || invocations[0].length === 0) {
				throw new Error("omp-unified-exec: host worktree rewrite did not produce one literal invocation");
			}
			result += renderInvocation(invocations[0], syntax);
		}
		cursor = start + segment.text.length;
	}
	return result + command.slice(cursor);
}
